import { AxisScale } from '@visx/axis';

/**
 *
 * @param value -
 * @param scale -
 */
export function mapValueToDomain(
  value: number,
  scale: AxisScale<number>,
): number {
  const [minDomain, maxDomain] = scale.domain();

  // offset for drawing it outside the chart.
  const offset = 10;

  if (isFinite(value)) {
    return scale(value) ?? 0;
  }

  const sign = Math.sign(value);
  const isPositiveInfinite = sign === 1;

  return isPositiveInfinite
    ? (scale(maxDomain) ?? 0) - offset
    : (scale(minDomain) ?? 0) + offset;
}
